import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"v1 capability coverage and acceptance","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/v1-coverage","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/v1-coverage.md","filePath":"en/architecture/v1-coverage.md"}'),o={name:"en/architecture/v1-coverage.md"};function n(i,e,c,l,b,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="v1-capability-coverage-and-acceptance" tabindex="-1">v1 capability coverage and acceptance <a class="header-anchor" href="#v1-capability-coverage-and-acceptance" aria-label="Permalink to &quot;v1 capability coverage and acceptance&quot;">​</a></h1><p>This page preserves v1 capability coverage and historical acceptance so maintainers can trace the specification, implementation and evidence from those revisions. Ticket states, measurements and acceptance versions below are historical records. Use <a href="./../docs/">Developer documentation</a> for current learning paths and GitHub Issues for live implementation status. The matrix maps the spec&#39;s <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">§8.6 feature coverage matrix</a> to actual source and migrated guides.</p><h2 id="current-development-entries" tabindex="-1">Current development entries <a class="header-anchor" href="#current-development-entries" aria-label="Permalink to &quot;Current development entries&quot;">​</a></h2><ol><li><strong>Start backend development</strong>: <a href="./../getting-started/quickstart">Quick start</a> verifies startup and HTTP; <a href="./project-structure">project structure</a> locates source.</li><li><strong>Add your business</strong>: <a href="./../guides/new-module">Add a module</a> connects Router/OpenAPI, followed by capability-specific guides.</li><li><strong>Verify and deliver</strong>: <a href="./../testing/feedback-loop">Feedback loop</a>, <a href="./../tutorials/single-machine-production">production deployment</a> and <a href="./../tutorials/backup-restore">independent restore</a>.</li><li><strong>Replace and look up</strong>: <a href="./../tutorials/example-removal">Remove reference business</a>, <a href="./boundaries">Core/business boundaries</a>, <a href="./../reference/api">API contract</a> and <a href="./../reference/config">configuration</a>.</li></ol><h2 id="core-capability-matrix" tabindex="-1">Core capability matrix <a class="header-anchor" href="#core-capability-matrix" aria-label="Permalink to &quot;Core capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Template capability</th><th>Run entry</th><th>Source guide</th><th>Follow along</th><th>Verification</th></tr></thead><tbody><tr><td>Registration, sessions, configuration</td><td><code>/register</code>; <code>POST /api/v1/auth/register</code>, <code>/auth/session</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity" target="_blank" rel="noreferrer">identity</a> (incl. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/password_reset" target="_blank" rel="noreferrer">password_reset</a>), <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/config.rs" target="_blank" rel="noreferrer">config.rs</a></td><td><a href="./../tutorials/registration">02</a> · <a href="./../tutorials/sessions">03</a> · <a href="./../tutorials/password-reset">18</a></td><td>registration/session/password-reset API tests, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/config.rs" target="_blank" rel="noreferrer">config</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/registration.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr><tr><td>Organization, RBAC</td><td><code>/members</code>; role changes, deactivation revokes sessions, last-owner protection</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/organization" target="_blank" rel="noreferrer">organization</a></td><td><a href="./../tutorials/members">08</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/members.rs" target="_blank" rel="noreferrer">members</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/members.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr><tr><td>CRUD, SQLx, migrations</td><td><code>just migrate</code>; the migration set and checksums must match the source</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/migrations" target="_blank" rel="noreferrer">migrations/</a></td><td><a href="./../tutorials/first-request">01</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/migration.rs" target="_blank" rel="noreferrer">migration</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/status.spec.ts" target="_blank" rel="noreferrer">e2e migration version</a></td></tr><tr><td>OpenAPI, SDK, multi-surface views</td><td><code>pnpm contracts:check</code>; Electron opens the same pages</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/packages/contracts" target="_blank" rel="noreferrer">contracts</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/packages/sdk/src" target="_blank" rel="noreferrer">sdk</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/packages/views/src" target="_blank" rel="noreferrer">views</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/desktop/src" target="_blank" rel="noreferrer">desktop</a></td><td><a href="./../tutorials/electron-shell">20</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/desktop/shell.spec.ts" target="_blank" rel="noreferrer">shell smoke</a>, IPC contract tests</td></tr><tr><td>RustFS / S3 / file permissions</td><td><code>bootstrap-storage</code> initializes the private bucket and browser CORS</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files" target="_blank" rel="noreferrer">files</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">object_storage.rs</a></td><td>— (covered by gates and stack startup)</td><td>bucket initialization check at every test-stack startup</td></tr><tr><td>Jobs, worker, idempotency</td><td><code>just dev</code> starts the worker; failed jobs can be retried explicitly</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/jobs" target="_blank" rel="noreferrer">jobs</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/idempotency" target="_blank" rel="noreferrer">idempotency</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/worker/src" target="_blank" rel="noreferrer">worker</a></td><td>— (covered by gates and tests)</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/jobs.rs" target="_blank" rel="noreferrer">jobs</a> (claim/heartbeat/retry)</td></tr><tr><td>Notification / mail</td><td>Registration and password-reset mail arrives in <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">Mailpit</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/notifications" target="_blank" rel="noreferrer">notifications</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/mail.rs" target="_blank" rel="noreferrer">mail.rs</a></td><td><a href="./../tutorials/password-reset">18</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/password-reset.spec.ts" target="_blank" rel="noreferrer">e2e</a>, mail key tooling tests</td></tr><tr><td>Audit / tracing</td><td><code>/audit</code>; <code>GET /api/v1/audit-events</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/audit" target="_blank" rel="noreferrer">audit</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/telemetry" target="_blank" rel="noreferrer">telemetry</a></td><td>— (covered by gates and tests)</td><td>telemetry tests (including the outage drill)</td></tr><tr><td>Redis / rate limiting</td><td><code>/system</code> shows cache and rate-limit status</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/rate_limit" target="_blank" rel="noreferrer">rate_limit</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/system/cache.rs" target="_blank" rel="noreferrer">system cache</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/platform/src/cache.rs" target="_blank" rel="noreferrer">platform cache</a></td><td><a href="./../tutorials/rate-limits">17</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/rate-limits.spec.ts" target="_blank" rel="noreferrer">e2e</a>, rate-limit support tests</td></tr><tr><td>API keys</td><td><code>/api-keys</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/api_keys" target="_blank" rel="noreferrer">api_keys</a> (issuance and session verification)</td><td>— (covered by gates and tests)</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/web/src/api-keys.test.tsx" target="_blank" rel="noreferrer">api-keys view test</a></td></tr><tr><td>Testing / performance</td><td><code>just perf-ci</code> (gate); nightly load/saturation/trajectory reports</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/perf" target="_blank" rel="noreferrer">scripts/perf</a> (incl. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/perf/baselines.json" target="_blank" rel="noreferrer">baselines.json</a>)</td><td>— (budgets run with <code>just check</code>)</td><td><code>just perf-ci</code>, budget/report unit tests, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly.yml</a></td></tr><tr><td>Deployment / recovery</td><td><code>just production-up</code> / <code>production-backup</code> / <code>production-restore-drill</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/compose.production.yaml" target="_blank" rel="noreferrer">compose.production.yaml</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/deploy/production" target="_blank" rel="noreferrer">deploy/production</a>, production-*.mjs</td><td><a href="./../tutorials/single-machine-production">21</a> · <a href="./../tutorials/backup-restore">22</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/tooling/production-compose.test.mjs" target="_blank" rel="noreferrer">production-compose</a>, backup manifest/sigv4 tooling tests</td></tr><tr><td>Documentation / removable examples</td><td><code>just check-core</code> (post-removal gate); <code>just docs</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/example-remove.mjs" target="_blank" rel="noreferrer">example-remove.mjs</a></td><td><a href="./../tutorials/example-removal">23</a></td><td>CI runs the full removal drill every PR, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">example-remove tooling tests</a></td></tr></tbody></table><h2 id="what-the-knowledge-base-example-demonstrates-removed-with-the-example" tabindex="-1">What the knowledge-base example demonstrates (removed with the example) <a class="header-anchor" href="#what-the-knowledge-base-example-demonstrates-removed-with-the-example" aria-label="Permalink to &quot;What the knowledge-base example demonstrates (removed with the example)&quot;">​</a></h2><p>This section is demonstrated by the knowledge-base example and disappears together with <a href="./../tutorials/example-removal">removing the examples</a>; after example removal the Core matrix above still holds, and a replacement example plugs in through the same public interfaces.</p><p>The &quot;business constraints, concurrency&quot; row of spec §8.6 is demonstrated entirely by the example:</p><table tabindex="0"><thead><tr><th>Template capability</th><th>Run entry</th><th>Source guide</th><th>Follow along</th><th>Verification</th></tr></thead><tbody><tr><td>Business constraints, concurrency</td><td>Saving on the edit page triggers 409; last-owner protection</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/domain.rs" target="_blank" rel="noreferrer">domain.rs</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/deletion.rs" target="_blank" rel="noreferrer">deletion.rs</a></td><td><a href="./../tutorials/edit-conflicts">06</a> · <a href="./../tutorials/deletion-cleanup">12</a></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/deletion.rs" target="_blank" rel="noreferrer">deletion</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/deletion.spec.ts" target="_blank" rel="noreferrer">e2e</a></td></tr></tbody></table><p>What the example demonstrates in the other rows:</p><ul><li><strong>Resource authorization</strong>: Reader/Editor grants and revocations → <a href="./../tutorials/library-grants">07</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/grants.rs" target="_blank" rel="noreferrer">grants.rs</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/knowledge-grants.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>Knowledge document CRUD, search, preview and pagination</strong> → <a href="./../tutorials/personal-documents">04</a> · <a href="./../tutorials/search-preview">05</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/knowledge.rs" target="_blank" rel="noreferrer">knowledge</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/knowledge.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>Attachment upload/download and Markdown references</strong> → <a href="./../tutorials/attachments">09</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">attachments.rs</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/attachments.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>ZIP export and job recovery</strong> → <a href="./../tutorials/document-exports">10</a> · <a href="./../tutorials/job-recovery">11</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/exports.rs" target="_blank" rel="noreferrer">exports</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/exports.spec.ts" target="_blank" rel="noreferrer">e2e</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/job-recovery.spec.ts" target="_blank" rel="noreferrer">recovery e2e</a></li><li><strong>Export notifications and read state</strong> → <a href="./../tutorials/export-notifications">13</a></li><li><strong>Audit traceability of knowledge operations</strong> → <a href="./../tutorials/audit-history">14</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/audit_knowledge.rs" target="_blank" rel="noreferrer">audit_knowledge</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/e2e/audit.spec.ts" target="_blank" rel="noreferrer">e2e</a></li><li><strong>API keys reading permitted documents</strong> → <a href="./../tutorials/api-keys">15</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/key_documents.rs" target="_blank" rel="noreferrer">key_documents</a></li><li><strong>Versioned body cache</strong> → <a href="./../tutorials/versioned-cache">16</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/cached_documents.rs" target="_blank" rel="noreferrer">cached_documents</a></li><li><strong>The observability example chain</strong> → <a href="./../tutorials/observability">19</a></li><li><strong>Tutorials for deterministic budgets, load/saturation/trajectory and the desktop render soak</strong> → <a href="./../tutorials/perf-gates">24</a> · <a href="./../tutorials/load-reports">25</a> · <a href="./../tutorials/desktop-soak">26</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/perf_documents.rs" target="_blank" rel="noreferrer">perf_documents</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/desktop/soak.spec.ts" target="_blank" rel="noreferrer">desktop soak</a></li><li><strong>Electron opening the knowledge example</strong> → <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/tests/desktop/knowledge-shell.spec.ts" target="_blank" rel="noreferrer">knowledge-shell</a></li><li><strong>The example ownership manifest</strong> → <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">examples/knowledge-base/manifest.json</a></li></ul><p>Example acceptance supplements: the renderer resource soak report is produced nightly by <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/perf/desktop-soak.mjs" target="_blank" rel="noreferrer">desktop-soak</a> (artifact kept 30 days); tutorials 04–19 and 24–26 shipped ticket by ticket with the example.</p><h2 id="acceptance-summary" tabindex="-1">Acceptance summary <a class="header-anchor" href="#acceptance-summary" aria-label="Permalink to &quot;Acceptance summary&quot;">​</a></h2><ul><li><strong>Default full stack</strong>: tutorials delivered ticket by ticket starting from <a href="./../tutorials/first-request">the first full-stack request</a>; daily gate <code>just check</code>, real browser journeys <code>just e2e</code>, milestone <code>just check-full</code>.</li><li><strong>Electron</strong>: <a href="./../tutorials/electron-shell">the secure shell tutorial</a> + desktop smoke (<code>just desktop-smoke</code>, every PR in CI).</li><li><strong>Mobile</strong>: not implemented and not planned for v1 (implementation ticket <a href="https://github.com/CaiZongyuan/axum-saas-template/issues/22" target="_blank" rel="noreferrer">#22</a> recorded as not planned). Spec §15.2 and the testing strategy&#39;s Mobile entries stay as design notes and are not to be implemented from (the implementation decision follows #22; the divergence is intentional); no corresponding checks, no documentation blanks.</li><li><strong>Performance</strong>: deterministic budgets are accepted every PR with <code>just check</code> (<code>perf-ci</code>); load/saturation/trajectory soak reports are produced only by <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly</a> (nightly, manual and release triggers), artifacts kept 30 days, never acting as a PR gate.</li><li><strong>Backup and restore</strong>: <a href="./../tutorials/backup-restore">backup and isolated-environment restore drill</a> verifies documents, attachments and jobs on an isolated restore environment; the archive carries no secrets, and the drill cleans up credentials and certificates at the end.</li><li><strong>Example removal</strong>: <a href="./../tutorials/example-removal">removing the examples</a> executes per the ownership manifest; CI&#39;s example-removal job drills the whole thing every PR; after removal <code>just check-core</code> is green.</li><li><strong>Generated references</strong>: the API contract is generated from OpenAPI (<code>contracts:check</code> guards drift), the configuration reference is generated from Settings and cross-checked against <code>.env.example</code>; the permission and job catalogs are carried by tutorial prose and have no generated reference yet — recorded honestly, not faked.</li></ul><h2 id="ui-and-multi-example-series-acceptance-57" tabindex="-1">UI and multi-example series acceptance (#57) <a class="header-anchor" href="#ui-and-multi-example-series-acceptance-57" aria-label="Permalink to &quot;UI and multi-example series acceptance (#57)&quot;">​</a></h2><p>The whole UI series (UI01–UI15, parent <a href="https://github.com/CaiZongyuan/axum-saas-template/issues/57" target="_blank" rel="noreferrer">#57</a>) — all 61 user stories — was accepted on the integrated revision 4f971ed plus this ticket&#39;s acceptance repairs (the head commit of the corresponding PR):</p><ul><li><strong>Gates and journeys</strong>: <code>just check</code>, <code>just check-full</code> (12 specs, 15 real-browser journeys, including database pause/recovery, a real rate-limit window, two-browser session isolation, Worker crash recovery and a real object-storage failure retry) and <code>just e2e-docs</code> (public site zh/en × light/dark × narrow screens and base paths) all pass on this revision. The legacy-fallback contracts — unknown paths fall back to the universal home, and notifications stay readable with understandable unavailable feedback after the target business is removed — are covered by the app-shell and notification contract tests, while the post-deletion/revocation &quot;no longer exists&quot; feedback keeps running inside the e2e journeys.</li><li><strong>Multi-example combinations</strong>: CI&#39;s example-removal job (every PR) drills, on the same revision, the dirty-copy refusal, dual → notes-only → core-only, an independent knowledge-only copy, and a new business joining through the public interfaces; every combination&#39;s gate (<code>check-core</code>, docs build, typecheck, frontend tests, web build, boundary check) passes. The desktop secure shell is verified by the desktop-smoke job (every PR).</li><li><strong>Performance budgets</strong>: the only budget-baseline change in the series is UI05 adding the design-system showroom and the icon catalog to the lazy-loading baseline (a tightening); the 400/500 KiB first-load ceilings in <code>perf-ci</code> were never raised, and the showroom and icon catalog stay out of the first bundle.</li><li><strong>Public pages</strong>: Landing, Documentation, Blog and Downloads — both languages, both themes, narrow-screen navigation, base paths, metadata and real CTAs — are covered by <code>e2e-docs</code> and the docs contract tests; Blog and Downloads clearly say &quot;coming soon&quot; instead of presenting placeholders as delivered.</li><li><strong>Tutorials and migration cleanup</strong>: online chapters are bilingual per the published list (<code>docs:check</code> enforces registration and consistency); bilingual tutorials, example registration and behavior tests shipped with their implementation tickets, and post-removal bilingual trimming is verified by the example-removal job&#39;s docs build. The old-message/old-docs migration items and unwired legacy plumbing are cleared. One gap remains: tutorial 16 (Redis body cache with database fallback) never got its English translation inside the owning ticket&#39;s scope; it keeps an honest pending marker and is tracked in <a href="https://github.com/CaiZongyuan/axum-saas-template/issues/96" target="_blank" rel="noreferrer">#96</a>.</li><li><strong>Acceptance repairs</strong>: the acceptance run exposed 7 early e2e journeys still assuming register/sign-in stays on the old home view and relying on the runner&#39;s default language (the UI04 device-language probe renders English). They now pin <code>zh-CN</code> following the existing password-reset pattern and assert the actual landing (register/sign-in enter the documents entry; the sign-out control lives on the universal home view). No new abstraction, no weakened assertion.</li><li><strong>Story 61</strong>: this section is the acceptance record for &quot;integrate the current v1 implementation and acceptance before the next round&quot;; the next UI/site round starts from this revision.</li></ul><h3 id="style-alignment-round-acceptance-ui-r1–r5-99–-103" tabindex="-1">Style-alignment round acceptance (UI-R1–R5, #99–#103) <a class="header-anchor" href="#style-alignment-round-acceptance-ui-r1–r5-99–-103" aria-label="Permalink to &quot;Style-alignment round acceptance (UI-R1–R5, #99–#103)&quot;">​</a></h3><p>After the first round merged, a second alignment round was executed and accepted ticket by ticket on the user&#39;s verified conclusion that the delivery&#39;s look and structure fell far short of the reference projects: tokens and component geometry (#104), the icon system entering the app (#105), the grouped settings layout (#106), shell slots and the single-mount layout route (#107), and the collapsed assembly default plus documentation/verification hygiene (#103). Gates and CI meet the same bar as round one (<code>just check</code>, <code>just e2e-docs</code>, and the verify/desktop-smoke/example-removal jobs); R5 extends the example-removal scenario into a five-combination drill that includes explicitly re-adding the notes example, and adds the in-app theme real-browser e2e (<code>tests/e2e/theme.spec.ts</code>). The gap analysis, per-ticket delivery and pixel-level before/after comparisons are recorded in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/handoffs/2026-09-29-ui-series-alignment.md" target="_blank" rel="noreferrer">UI series handoff report</a>; the design-side record lives in <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/ui/design.md" target="_blank" rel="noreferrer">docs/ui/design.md §5, the alignment round</a>.</p><h2 id="release-and-reproduction" tabindex="-1">Release and reproduction <a class="header-anchor" href="#release-and-reproduction" aria-label="Permalink to &quot;Release and reproduction&quot;">​</a></h2><p>The site publishes at <a href="https://caizongyuan.github.io/axum-saas-template/" target="_blank" rel="noreferrer">https://caizongyuan.github.io/axum-saas-template/</a>, continuously updated with <code>main</code>; the &quot;source version&quot; in every page&#39;s footer is the repository commit that page&#39;s acceptance corresponds to, and the publish task verifies the built docs against the commit before going live. Full reproduction steps are in <a href="./../getting-started/quickstart">quick start</a>. The v1 milestone verification command: <code>just check-full</code>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/architecture/v1-coverage.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',24)])])}const u=t(o,[["render",n]]);export{h as __pageData,u as default};
